<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { onMounted, ref, watch } from "vue";
import { useResellerAuth } from "@papilio/auth";
import { item, request, query, type Page, type Customer, type CustomerAccessState, type Reseller } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
import CustomerAccess from "../components/CustomerAccess.vue";
const auth=useResellerAuth(),rows=ref<Customer[]>([]),selected=ref<Customer|null>(null),profile=ref<Reseller|null>(null);
const page=ref(1),pages=ref(1),total=ref(0),q=ref(""),loading=ref(false),busy=ref(false),error=ref(""),profileError=ref(""),notice=ref("");
const name=ref(""),newName=ref(""),telegramId=ref(""),overrideAccess=ref(false),access=ref<CustomerAccessState|null>(null);
let version=0,selectionVersion=0;
async function load():Promise<void>{const current=++version;loading.value=true;error.value="";try{const result=await request<Page<Customer>>(`/v1/reseller/customers?${query({page:page.value,q:q.value})}`);if(current!==version)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(current===version)error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{if(current===version)loading.value=false;}}
async function loadProfile():Promise<void>{profileError.value="";try{const result=await item<Reseller>("/v1/reseller/profile");profile.value=result;if(!overrideAccess.value)access.value={...result.policy.new_customer_access};}catch(cause){profileError.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
async function select(row:Customer,preserve=false):Promise<void>{if(busy.value)return;const current=++selectionVersion;error.value="";try{const result=await item<Customer>(`/v1/reseller/customers/${row.id}`);if(current!==selectionVersion)return;const same=selected.value?.id===row.id;selected.value=result;if(!preserve||!same)name.value=result.display_name;}catch(cause){if(current===selectionVersion)error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
async function create():Promise<void>{if(busy.value||!profile.value||!auth.can("customers","create"))return;busy.value=true;error.value="";notice.value="";try{const row=await item<Customer>("/v1/reseller/customers","POST",{display_name:newName.value,telegram_id:telegramId.value?Number(telegramId.value):null,access:overrideAccess.value?access.value:null});selected.value=row;name.value=row.display_name;newName.value="";telegramId.value="";createOpen.value=false;notice.value="Customer created in this reseller account.";page.value=1;await load();}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{busy.value=false;}}
async function save():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("customers","update"))return;busy.value=true;error.value="";notice.value="";try{selected.value=await item<Customer>(`/v1/reseller/customers/${row.id}`,"PATCH",{display_name:name.value});notice.value="Customer name saved.";await load();}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}finally{busy.value=false;}}
watch(q,()=>{page.value=1;void load();});onMounted(()=>{void load();void loadProfile();});
const createOpen=ref(false);
</script>
<template><div class="page-head"><div><p class="eyebrow">CUSTOMER WORKSPACE</p><h1>Reseller customers</h1><p class="subtitle">Manage customers and start operations from their selected records.</p></div><button class="btn secondary" :disabled="loading||busy" @click="load">Refresh</button><button v-if="auth.can('customers','create')" class="btn" :disabled="busy" @click="createOpen=true">+ Create customer</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p><div :class="{split:!!selected}"><section class="card"><div class="card-pad"><label class="field"><span>Search customers Customer</span><input v-model="q" maxlength="120"/></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Telegram</th><th>Account / service / renewal</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td>{{row.display_name}}</td><td>{{faNumber(row.telegram_id)}}</td><td>{{row.is_active?'Active':'Inactive'}} / {{row.services_enabled?'Enabled':'Paused'}} / {{row.renewals_enabled?'Enabled':'Paused'}}</td></tr></tbody></table><p v-if="loading" class="empty">Loading…</p><p v-else-if="!rows.length&&!error" class="empty">No customers found.</p></div><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} Customer</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section><div class="stack"><section v-if="selected" class="card card-pad"><h2>{{selected.display_name}}</h2><p>ID {{faNumber(selected.id)}} · Telegram {{faNumber(selected.telegram_id)}}</p><p v-if="selected.service_hold_pending" class="hint-box">Service suspension is awaiting node confirmation.</p><RouterLink v-if="auth.can('subscriptions')" :to="`/reseller/customers/${selected.id}/subscriptions`" class="btn secondary">Purchases and subscriptions</RouterLink><form v-if="auth.can('customers','update')" class="form-grid" @submit.prevent="save"><label class="field"><span>Customer display name</span><input v-model="name" minlength="1" maxlength="120" required :disabled="busy"/></label><button class="btn" :disabled="busy||!name.trim()">Save name</button></form><button class="btn secondary" :disabled="busy" @click="select(selected,true)">Refresh record and retain draft</button></section><CustomerAccess v-if="selected" :key="selected.id" :customer="selected" realm="reseller" :policy-allows="profile?.policy.customer_access_override_enabled" @changed="selected=$event;load()"/><Modal v-if="auth.can('customers','create')" v-model="createOpen" title="Create customer" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="profileError" class="message error">{{profileError}} <button class="btn secondary" @click="loadProfile">Retry</button></p><p v-if="profile&&!profile.policy.customer_creation_enabled" class="hint-box">Customer creation is paused by the current policy.</p><form v-if="profile?.policy.customer_creation_enabled" class="form-grid" @submit.prevent="create"><fieldset :disabled="busy" class="form-grid"><label class="field"><span>Name Create customer</span><input v-model="newName" minlength="1" maxlength="120" required/></label><NumField v-model="telegramId" label="Telegram ID (optional)"/><p class="hint-box">Existing Telegram accounts cannot be reassigned. Duplicate registrations are rejected.</p><label v-if="profile.policy.customer_access_override_enabled" class="check-row"><input v-model="overrideAccess" type="checkbox"/>Customize initial access</label><template v-if="overrideAccess&&access"><label class="check-row"><input v-model="access.is_active" type="checkbox"/>Account enabled</label><label class="check-row"><input v-model="access.services_enabled" type="checkbox"/>Service Enabled</label><label class="check-row"><input v-model="access.renewals_enabled" type="checkbox"/>Renewal Enabled</label></template><p v-else class="hint-box">Current defaults: account {{profile.policy.new_customer_access.is_active?'Active':'Inactive'}} · Service {{profile.policy.new_customer_access.services_enabled?'Enabled':'Paused'}} · Renewal {{profile.policy.new_customer_access.renewals_enabled?'Enabled':'Paused'}}</p><button class="btn" :disabled="!newName.trim()">Create customer</button></fieldset></form></Modal></div></div></template>
<style scoped>fieldset{border:0;padding:0}</style>
